using System;
using System.Collections.Generic;

namespace OpenClaw.Shared.Coding.BuildAnything;

/// <summary>
/// Supported project archetypes generated by the Build Anything engine.
/// </summary>
public enum CraftProjectType
{
    WebSinglePageApp,
    WebFullStack,
    DesktopApp,
    CliTool,
    Microservice,
    Canvas2D,
    DocumentationSite
}

/// <summary>
/// Natural language project creation specification.
/// </summary>
public sealed record CraftProjectSpec
{
    public required string Name { get; init; }
    public required string Description { get; init; }
    public CraftProjectType TargetType { get; init; } = CraftProjectType.WebSinglePageApp;
    public string Framework { get; init; } = "Vite/React";
    public IReadOnlyList<string> TechStack { get; init; } = new[] { "HTML5", "CSS3", "JavaScript", "React" };
    public required string TargetDirectory { get; init; }
    public IReadOnlyList<string> Requirements { get; init; } = Array.Empty<string>();
    public string ThemePreference { get; init; } = "Dark";
}

/// <summary>
/// A file generated as part of a clean-room project build.
/// </summary>
public sealed record CraftGeneratedFile
{
    public required string RelativePath { get; init; }
    public required string Content { get; init; }
    public string Purpose { get; init; } = "Source";
    public int SizeBytes => System.Text.Encoding.UTF8.GetByteCount(Content);
}

/// <summary>
/// Discovered build outputs and artifacts (matching Craft Anything's outputs.rs).
/// </summary>
public sealed record CraftBuildOutput
{
    public string? SiteDirectory { get; init; } // Folder containing index.html (e.g. dist, build, out, or root)
    public string? BuiltExecutablePath { get; init; } // Built native binary or program (e.g. default-run program)
    public string? PreviewUrl { get; init; } // Direct file:/// URL or localhost URL for WebView2 preview
    public bool BuildSuccess { get; init; }
    public string OutputType { get; init; } = "WebSite"; // "WebSite", "NativeExecutable", "CliTool"
    public string ExecutionDiagnostics { get; init; } = string.Empty;
    public IReadOnlyList<string> ArtifactFiles { get; init; } = Array.Empty<string>();
}

/// <summary>
/// State of a Build Anything creation session.
/// </summary>
public sealed record CraftCreationSession
{
    public required string SessionId { get; init; }
    public required CraftProjectSpec Spec { get; init; }
    public List<CraftGeneratedFile> GeneratedFiles { get; init; } = new();
    public CraftBuildOutput? Output { get; set; }
    public DateTimeOffset CreatedAt { get; init; } = DateTimeOffset.UtcNow;
    public string Status { get; set; } = "Initialized";
    public double ProgressPercentage { get; set; }
}
